 const lug=c.lugares.map((l,i)=>{const p=`lugares.${i}`;if(!l.quienes){const e=c.empleadores.find(x=>x.id===l.emp);l.quienes=e&&e.titular?[e.titular]:[];}return card(p,`<div style="grid-column:1/-1">${FC.dirH(p+'.dir','Dirección completa',{nota:false,lugar:1,usar:1})}</div><div style="grid-column:1/-1" class="x-q"><span class="x-qt">¿Desde qué fecha y hasta qué fecha estuvo trabajando en este lugar?</span></div>${fld(p+'.desde','Desde',{type:'date'})}${fld(p+'.hasta','Hasta',{type:'date'})}<div class="roles">${sameBtn([[p+'.desde','rel.inicio']],'Misma fecha de inicio del trabajo')}${sameBtn([[p+'.hasta','@fin']],'Misma fecha de fin del trabajo')}</div><div style="grid-column:1/-1" class="x-q"><span class="x-qt">¿Qué empleadores estaban en este centro de trabajo?</span>${empPerOpts.length?chips(p+'.quienes',empPerOpts,'Marque todos los que correspondan'):'<p class="x-empty">Primero añada a los empleadores (arriba).</p>'}</div>`,'Lugar de trabajo '+(i+1));}).join('');
 b+=sec('Centros de trabajo: direcciones',(lug||'<p class="x-empty">Ningún lugar todavía.</p>')+addBtn('lugares','Añadir otro lugar de trabajo'),FC.esB(c)?'El local, la oficina o las obras donde trabajaba. Si eran varias obras, añada cada una.':'La casa o casas donde trabajaba.');

