 if(!e.tipoEmp)return h+'<p class="x-help" style="grid-column:1/-1">Elija primero si es una empresa o una persona: después se pide el CIF (o el NIF) para buscar sus datos.</p>';
 const jur=e.tipoEmp!=='fisica',id=(e.cif||'').toUpperCase().replace(/[\s.\-]/g,''),m=jur?FC.cifCheck(e.cif):FC.nifCheck(e.cif),q=jur?'CIF':'NIF';
 h+=`${fld(p+'.cif',jur?'CIF de la empresa':'NIF de la persona (DNI o NIE del autónomo)',{rr:1,span:2})}${m?`<div class="x-flag" style="grid-column:1/-1">${esc(m)}</div>`:''}`
