  +op('sal.pagas','¿Le pagaban pagas extra?',[['si','Sí'],['no','No'],['ns','No lo sabe']],{req:1,help:'Las pagas extra son dos al año (normalmente verano y Navidad), aparte del sueldo del mes.'})+(c.sal.pagas==='si'?txt('sal.pagasTxt','¿Cuánto y cuándo se las pagaban?',{nota:false}):'')
  +Q('sal.entrega','¿Quién le entregaba el dinero en mano?',chips('sal.entrega',perOpts()),{nota:false})+txt('sal.entregaDonde','¿Dónde se lo entregaban?',{ph:'en la cocina, en la puerta, en la calle…',nota:false})+Q('sal.entregaPresentesP','¿Había alguien presente cuando le pagaban? ¿Quién?',chips('sal.entregaPresentesP',perOpts(),'Marque a las personas de la ficha que estaban delante')+`<div class="x-inrow"><input class="x-in" id="${pid('sal.entregaPresentes')}" data-p="sal.entregaPresentes" aria-label="Otras personas presentes o aclaraciones" placeholder="Otras personas o aclaraciones" value="${esc(C().sal.entregaPresentes||'')}"></div>`,{nota:false})
