function altaMes(c){if(c.rel.alta!=='si')return '';const ini=SF.pd(c.rel.inicio);return c.altas.map((a,i)=>{const p=`altas.${i}`,t=SF.pd(a.alta);if(t==null)return `<div class="x-q"><span class="x-qt">Mes en que ${gC('la','lo')} dieron de alta</span><p class="x-help">Ponga la fecha del alta ${i+1} en «Empleadores y lugares» para preguntar cómo le pagaron ese mes.</p></div>`;if(ini==null||t<=ini)return '';
 return `<div class="x-q"><span class="x-qt">Mes en que ${gC('la','lo')} dieron de alta (${esc(fmt(a.alta))})</span><div class="x-help">Antes trabajaba sin alta. Pregunte cuánto le pagaron ese mes, en bruto y en neto, y de qué fecha a qué fecha era ese pago. Este mes va en su propia tabla en la papeleta.</div></div><div class="x-p" style="border:0;padding:0">${fld(p+'.pagoBruto','Importe bruto (euros)',{type:'number'})}${fld(p+'.pagoNeto','Importe neto (euros)',{type:'number'})}${fld(p+'.pagoDesde','El pago era desde',{type:'date'})}${fld(p+'.pagoHasta','Hasta',{type:'date'})}${fld(p+'.pagoMes','¿Qué día se lo pagaron?',{type:'date'})}${fld(p+'.pagoMesForma','¿Cómo se lo pagaron?',{sel:[['efectivo','Efectivo'],['transferencia','Transferencia'],['bizum','Bizum'],['nomina','Con nómina'],['otra','Otra']]})}${fld(p+'.pagoMesObs',`Observaciones del pago (si cambió algo al ${gC('darla','darlo')} de alta)`,{span:2})}</div>`;}).join('');}
FC.vacMetodoH=()=>{const T2=FC.calcT2(FC.st);if(!T2.ambas)return '';const mx=T2.totM>T2.totD?'dinero':T2.totD>T2.totM?'dias':'';
 return `<div class="x-card x-stack"><h3 class="x-h3">Formas de descontar las vacaciones</h3><p>Hay días disfrutados y también dinero pagado por vacaciones. Total que se le debe de vacaciones:</p><ul class="x-mini"><li${mx==='dias'?' class="w"':''}>Restando los días disfrutados: <b>${eur(T2.totD)}</b>${mx==='dias'?' · <b>es la mayor</b>':''}</li><li${mx==='dinero'?' class="w"':''}>Restando el dinero pagado: <b>${eur(T2.totM)}</b>${mx==='dinero'?' · <b>es la mayor</b>':''}</li><li>En cada año, la forma más favorable: <b>${eur(T2.totX)}</b>${T2.totX>Math.max(T2.totD,T2.totM)+0.005?' · <b>la más alta</b> (útil para negociar un acuerdo)':' · coincide con la mayor'}</li></ul>`
  +op('vac.metodo','¿Cuál se usa en la tabla de vacaciones?',[['dias','Restar los días disfrutados ('+eur(T2.totD)+')'],['dinero','Restar el dinero pagado ('+eur(T2.totM)+')'],['mixto','En cada año, la más favorable ('+eur(T2.totX)+')']],{nota:false,help:T2.elegido?'':'Mientras no se elija, se usa la mayor de las dos primeras (la misma forma para todos los años).'})+'</div>';};
FC.pagasMetodoH=()=>{const st=FC.st,c=C();const T2=FC.calcT2(st);const A=FC.calcT1(st,'prorrata'),B=FC.calcT1(st,'separado');if(!A.rows.length)return '';const tA=FC.totales({T1:A,T2,c}),tB=FC.totales({T1:B,T2,c});const mx=tB.principal>tA.principal+0.005?'separado':tA.principal>tB.principal+0.005?'prorrata':'';
 return `<div class="x-card x-stack"><h3 class="x-h3">Pagas extra: dos formas de calcularlas</h3><ul class="x-mini"><li${mx==='prorrata'?' class="w"':''}>Prorrateadas en cada mes (SMI × 14 / 12, como el escrito de ejemplo): total principal <b>${eur(tA.principal)}</b>${mx==='prorrata'?' · <b>es la mayor</b>':''}</li><li${mx==='separado'?' class="w"':''}>Por separado (cada mes con SMI × 12 / 12 y una tabla aparte con dos pagas al año): total principal <b>${eur(tB.principal)}</b>${mx==='separado'?' · <b>es la mayor</b>':''}</li></ul>`
  +op('abg.pagasMetodo','¿Cómo se calculan las pagas extra en la papeleta?',[['prorrata','Prorrateadas en cada mes ('+eur(tA.principal)+')'],['separado','Por separado, en su propia tabla ('+eur(tB.principal)+')']],{nota:false,help:c.abg.pagasMetodo?'':'Mientras no se elija, se usan prorrateadas, como en el escrito de ejemplo.'})+'</div>';};
