 const pressed=el=>[...el.querySelectorAll('.x-o[aria-pressed="true"],.x-chip[aria-pressed="true"],.fc-day[aria-pressed="true"]')].filter(b=>!b.classList.contains('ns')).map(b=>T(b.textContent));
